					xs!!.a_bot = (links!!.xsect_a_bot)!!.a!![uj.toInt()]
					xs!!.s_bot = (links!!.xsect_s_bot)!!.a!![uj.toInt()]
					xs!!.r_bot = (links!!.xsect_r_bot)!!.a!![uj.toInt()]
					if (((batch_shape == 22) || (batch_shape == 23)) || (batch_shape == 25)) {
						var ci: Int = (links!!.xsect_curve)!!.a!![uj.toInt()]
						if ((ci >= 0) && (java.lang.Long.compareUnsigned(ci.toLong(), (ctx!!.transect_tables)!!.size()) < 0)) {
							var td: transect_TransectData? = (ctx!!.transect_tables)!!.a!![ci.toLong().toInt()] as transect_TransectData?
							xs!!.transect = ci
							xs!!.area_tbl = cpp.PtrD(td!!.area_tbl, 0L)
							xs!!.hrad_tbl = cpp.PtrD(td!!.hrad_tbl, 0L)
							xs!!.width_tbl = cpp.PtrD(td!!.width_tbl, 0L)
							xs!!.area_lut = td!!.area_lut
							xs!!.transect_tbl_size = F_transect.N_TRANSECT_TBL
						}
					}
					if (wantEvap) {
						var top_width: Double = 0.0
						if ((batch_shape == 22) || (batch_shape == 23)) {
							top_width = if (xs!!.y_full > 0.0) xs!!.w_max * cpp.M.min_d_d(depth / xs!!.y_full, 1.0) else 0.0
						} else {
