						} else {
							if (d_seep >= xs!!.yw_max) {
								d_seep = xs!!.yw_max
							}
							width = F_xsect.getWofY(xs, d_seep)
						}
						seep_loss.v = (k_seep * width) * length
						seep_loss.v *= (ctx!!.climate_state)!!.infil_factor
						if (gw_two_way) {
							seep_loss.v *= F_hydraulics.aquiferSeepFactor(depth, (CD!!.gw_head_rel)!!.a!![ucr.toInt()], (CD!!.gw_dc)!!.a!![ucr.toInt()])
							seep_loss.v = F_hydraulics.capAquiferGain(seep_loss.v, (CD!!.gw_gain_max)!!.a!![ucr.toInt()])
						}
					}
				}
				var total: Double = evap_loss + cpp.M.max_d_d(seep_loss.v, 0.0)
				if ((total > 0.0) && ((this.model_ == RouteModel.DYNWAVE) || (this.model_ == RouteModel.FV))) {
					var q_avail: Double = (links!!.volume)!!.a!![uj.toInt()] / (dt * ((CD!!.barrels)!!.a!![ucr.toInt()]).toDouble())
					if ((total > q_avail) && (q_avail >= 0.0)) {
						var ratio: Double = q_avail / total
						evap_loss *= ratio
						if (seep_loss.v > 0.0) {
							seep_loss.v *= ratio
						}
					}
				}
			}
			F_hydraulics.applySeepageForcing(ctx, uj, seep_loss)
			(CD!!.evap_loss_rate)!!.a!![ucr.toInt()] = evap_loss
			(CD!!.seep_loss_rate)!!.a!![ucr.toInt()] = seep_loss.v
			j++
		}
	}

	open fun refreshFvBoundaryFlows(ctx: SimulationContext?, t_elapsed: Double, eval_structures: FN3?) {
		var impl: fv_ExplicitFvSolver? = this.fv_solver_ as? fv_ExplicitFvSolver
		if (!(impl !== null)) {
			return
		}
		this.accumulateStructureFlows(ctx, t_elapsed)
		var nn: Int = ctx!!.n_nodes()
		var n: Int = 0
		__L1@ while (n < nn) {
			var un: Long = n.toLong()
			if ((((this.fv_mesh_!!.node_kind)!!.a!![un.toInt()]).toInt() and 0xFF) == 1) {
				n++
				continue@__L1
			}
			var depth: Double = (this.fv_state_!!.node_head)!!.a!![un.toInt()] - (this.fv_mesh_!!.node_invert)!!.a!![un.toInt()]
			((ctx!!.nodes)!!.depth)!!.a!![un.toInt()] = cpp.M.max_d_d(0.0, depth)
			((ctx!!.nodes)!!.head)!!.a!![un.toInt()] = (this.fv_state_!!.node_head)!!.a!![un.toInt()]
			n++
		}
		F_outfall.setAllOutfallDepths(ctx, t_elapsed)
		var n_2: Int = 0
		__L2@ while (n_2 < nn) {
			var un_2: Long = n_2.toLong()
			if (((ctx!!.nodes)!!.type)!!.a!![un_2.toInt()] != NodeType.OUTFALL) {
				n_2++
				continue@__L2
			}
			this.fv_fixed_head_!!.a!![un_2.toInt()] = ((ctx!!.nodes)!!.invert_elev)!!.a!![un_2.toInt()] + ((ctx!!.nodes)!!.depth)!!.a!![un_2.toInt()]
			n_2++
		}
		eval_structures!!.invoke()
	}

	open fun accumulateStructureFlows(ctx: SimulationContext?, t_now: Double) {
		var span: Double = t_now - this.fv_struct_t_prev_
		if (span <= 0.0) {
			return
		}
		var j: Int = 0
		__L1@ while (j < ctx!!.n_links()) {
			var uj: Long = j.toLong()
			if (((ctx!!.links)!!.type)!!.a!![uj.toInt()] == LinkType.CONDUIT) {
				j++
				continue@__L1
			}
			this.fv_struct_int_!!.a!![uj.toInt()] += this.fv_struct_flow_!!.a!![uj.toInt()] * span
			j++
		}
		this.fv_struct_t_prev_ = t_now
	}

