	open fun executeSteadyFlow(ctx: SimulationContext?, dt: Double): Int {
		var links: LinkData? = ctx!!.links
		var nodes: NodeData? = ctx!!.nodes
		var order: cpp.VecI? = if (this.steady_sorted_links_!!.empty()) (FN101 __lam1@{ 
				if (!Router.S_fallback_37_done) {
					Router.S_fallback_37 = cpp.VecI()
					Router.S_fallback_37_done = true
				}
				var nl: Int = ctx!!.n_links()
				Router.S_fallback_37!!.resize_ul(nl.toLong())
				var j: Int = 0
				__L2@ while (j < nl) {
					Router.S_fallback_37!!.a!![j.toLong().toInt()] = j
					j++
				}
				return@__lam1 Router.S_fallback_37
			})!!.invoke() else this.steady_sorted_links_
		this.steady_storage_updated_!!.assign_ul_T((ctx!!.n_nodes()).toLong(), (0).toByte())
		this.steady_y_!!.assign_ul_T((ctx!!.n_links()).toLong(), 0.0)
		var idx: Int = 0
		__L3@ while (idx < (order!!.size()).toInt()) {
			var j_2: Int = order!!.a!![idx.toLong().toInt()]
			var uj: Long = j_2.toLong()
			var n1s: Int = (links!!.node1)!!.a!![uj.toInt()]
			if (((n1s >= 0) && ((nodes!!.type)!!.a!![n1s.toLong().toInt()] == NodeType.STORAGE)) && (!((this.steady_storage_updated_!!.a!![n1s.toLong().toInt()]).toInt() != 0))) {
				F_kinwave.updateStorageState(ctx, this.structures_, order, idx, n1s, dt)
				this.steady_storage_updated_!!.a!![n1s.toLong().toInt()] = (1).toByte()
			}
			if ((links!!.type)!!.a!![uj.toInt()] != LinkType.CONDUIT) {
				var n1: Int = (links!!.node1)!!.a!![uj.toInt()]
				var n2: Int = (links!!.node2)!!.a!![uj.toInt()]
				var q: Double = F_kinwave.getLinkInflow(ctx, this.structures_, j_2, dt)
				(links!!.flow)!!.a!![uj.toInt()] = q
				if (n1 >= 0) {
					(nodes!!.outflow)!!.a!![n1.toLong().toInt()] += q
				}
				if (n2 >= 0) {
					(nodes!!.inflow)!!.a!![n2.toLong().toInt()] += q
				}
				idx++
				continue@__L3
			}
			var CD: ConduitData? = (ctx!!.link_subtypes)!!.conduits
			var ucr: Long = ((ctx!!.link_subtypes)!!.conduit_row(j_2)).toLong()
			if ((links!!.xsect_shape)!!.a!![uj.toInt()] == XsectShape.DUMMY) {
				var n1_2: Int = (links!!.node1)!!.a!![uj.toInt()]
				var n2_2: Int = (links!!.node2)!!.a!![uj.toInt()]
				var q_2: Double = F_kinwave.getLinkInflow(ctx, this.structures_, j_2, dt)
				(links!!.flow)!!.a!![uj.toInt()] = q_2
				if (n1_2 >= 0) {
					(nodes!!.outflow)!!.a!![n1_2.toLong().toInt()] += q_2
				}
				if (n2_2 >= 0) {
					(nodes!!.inflow)!!.a!![n2_2.toLong().toInt()] += q_2
				}
				(links!!.depth)!!.a!![uj.toInt()] = 0.0
				(links!!.volume)!!.a!![uj.toInt()] = 0.0
				idx++
				continue@__L3
			}
			var n1_3: Int = (links!!.node1)!!.a!![uj.toInt()]
			var qin: Double = 0.0
			if (n1_3 >= 0) {
				qin = F_kinwave.getLinkInflow(ctx, this.structures_, j_2, dt)
			}
			var barrels: Double = cpp.M.max_i_i((CD!!.barrels)!!.a!![ucr.toInt()], 1).toDouble()
			var q_3: Double = qin / barrels
			var loss_rate: Double = F_kinwave.capConduitLoss(ctx, ucr, cpp.SysMath.Abs_d(q_3))
			q_3 -= loss_rate
			if (q_3 < 0.0) {
				q_3 = 0.0
			}
			var xs: XSectParams? = F_.buildXSP_Routing(ctx, uj)
			var q_full: Double = (CD!!.q_full)!!.a!![ucr.toInt()]
			var a_full: Double = (links!!.xsect_a_full)!!.a!![uj.toInt()]
			var a: Double = 0.0
			if (q_3 >= q_full) {
				q_3 = q_full
				a = a_full
				qin = q_3 * barrels
			} else {
				var beta: Double = (CD!!.beta)!!.a!![ucr.toInt()]
				if (beta > 0.0) {
					var s: Double = q_3 / beta
					a = F_xsect.getAofS(xs, s)
				} else {
					a = 0.0
				}
			}
			var qout: Double = q_3 * barrels
			(links!!.flow)!!.a!![uj.toInt()] = qout
			if (n1_3 >= 0) {
				(nodes!!.outflow)!!.a!![n1_3.toLong().toInt()] += qin
			}
			var n2_3: Int = (links!!.node2)!!.a!![uj.toInt()]
			if (n2_3 >= 0) {
				(nodes!!.inflow)!!.a!![n2_3.toLong().toInt()] += qout
			}
			var y: Double = F_xsect.getYofA(xs, a)
			var length: Double = (CD!!.true_length)!!.a!![ucr.toInt()]
			if (length <= 0.0) {
				length = (CD!!.length)!!.a!![ucr.toInt()]
			}
			(links!!.depth)!!.a!![uj.toInt()] = y
			(links!!.volume)!!.a!![uj.toInt()] = (a * length) * barrels
			this.steady_y_!!.a!![uj.toInt()] = y
			(CD!!.full_state)!!.a!![ucr.toInt()] = if ((a_full > 0.0) && (a >= a_full)) (3).toByte() else (0).toByte()
			idx++
		}
		F_kinwave.finishRouting(ctx, this.structures_, order, this.steady_storage_updated_, this.steady_y_, this.steady_y_, dt)
		return 1
	}

